# Managed by Bellhop sync-proxy. Do not edit: changes here are replaced on the next sync.
client_max_body_size 0;
proxy_buffering off;
proxy_request_buffering off;
proxy_read_timeout 1d;
proxy_send_timeout 1d;
proxy_buffers 8 16k;
proxy_buffer_size 32k;

location / {
        proxy_pass http://192.0.2.20:81;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-For $remote_addr;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-Host $host;
        proxy_set_header X-Forwarded-Port 443;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $http_connection;
        auth_request /outpost.goauthentik.io/auth/nginx;
        error_page 401 = @goauthentik_proxy_signin;
        auth_request_set $bellhop_auth_cookie $upstream_http_set_cookie;
        add_header Set-Cookie $bellhop_auth_cookie;
        auth_request_set $bellhop_authentik_username $upstream_http_x_authentik_username;
        proxy_set_header X-authentik-username $bellhop_authentik_username;
}

location ^~ "/api/" {
        proxy_pass http://192.0.2.20:81;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-For $remote_addr;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-Host $host;
        proxy_set_header X-Forwarded-Port 443;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $http_connection;
}

location = "/health" {
        proxy_pass http://192.0.2.20:81;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-For $remote_addr;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-Host $host;
        proxy_set_header X-Forwarded-Port 443;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $http_connection;
}

location /outpost.goauthentik.io {
        proxy_pass http://192.0.2.5:9000/outpost.goauthentik.io;
        proxy_set_header Host $host;
        proxy_set_header X-Original-URL $scheme://$host$request_uri;
        add_header Set-Cookie $bellhop_auth_cookie;
        auth_request_set $bellhop_auth_cookie $upstream_http_set_cookie;
        proxy_pass_request_body off;
        proxy_set_header Content-Length "";
}

location @goauthentik_proxy_signin {
        internal;
        add_header Set-Cookie $bellhop_auth_cookie;
        return 302 /outpost.goauthentik.io/start?rd=$scheme://$host$request_uri;
}
